<?php
require_once __DIR__.'/config/bootstrap.php';
require_login();
$id=(int)($_GET['id']??0);
$stmt=$pdo->prepare("SELECT s.*,u.name AS author,u.role AS author_role,c.name AS category_name FROM submissions s JOIN users u ON u.id=s.user_id LEFT JOIN categories c ON c.id=s.category_id WHERE s.id=?");
$stmt->execute([$id]); $item=$stmt->fetch();
if(!$item){http_response_code(404); render_header('Not found'); echo '<main id="main" class="container section"><h1>Resource not found</h1><p>This archive record does not exist.</p></main>'; render_footer(); exit;}
if(!can_edit_submission($item)){http_response_code(403); render_header('Access denied'); echo '<main id="main" class="container section"><div class="denied"><h1>403 · Access denied</h1><p>You can only edit your own Pending or Returned submissions. Admins can edit any record.</p><a class="button button-primary" href="dashboard.php">Back to dashboard</a></div></main>'; render_footer(); exit;}
render_header('Edit resource');
$isOwner=(int)current_user()['id']===(int)$item['user_id'];
?>
<main id="main" class="section role-page role-<?=e(current_user()['role'] ?? 'student')?>"><div class="container form-page"><div class="form-intro"><p class="eyebrow">EDIT RECORD</p><h1>Edit resource</h1><p class="muted">Change the details below. <?php if ($isOwner && $item['status']==='returned'): ?>Saving a returned record sends it back for review as Pending, and the old feedback is cleared.<?php elseif ($isOwner): ?>Saving keeps the record Pending.<?php else: ?>As admin, saving keeps the current review status.<?php endif; ?> Changing Public to Private hides the record from the public catalog, preview, and download at once.</p></div>
<form class="panel stack-form" action="api/edit.php" method="post" enctype="multipart/form-data" data-edit-form><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="submission_id" value="<?=(int)$item['id']?>">
<div class="form-grid"><label class="full-field">Resource title <span class="required">*</span><input name="title" required maxlength="180" value="<?=e($item['title'])?>"></label>
<label>Category <span class="required">*</span><select name="category_id" required><?php foreach(category_rows($pdo) as $c): ?><option value="<?=$c['id']?>" <?=(int)$item['category_id']===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></label>
<label>Academic year<input name="academic_year" maxlength="20" pattern="[0-9]{4}-[0-9]{4}" title="Use the form YYYY-YYYY, for example 2025-2026" value="<?=e($item['academic_year'])?>" placeholder="e.g. 2025-2026"></label>
<label class="full-field">Short description <span class="required">*</span><textarea name="description" required rows="4" maxlength="3000"><?=e($item['description'])?></textarea></label>
<label class="full-field">Keywords<input name="keywords" maxlength="500" value="<?=e($item['keywords'])?>" placeholder="research, database, programming"></label>
<div class="full-field"><span class="field-label">Resource type <span class="required">*</span></span><div class="choice-row"><label class="choice"><input type="radio" name="resource_type" value="file" <?=($item['resource_type']==='file')?'checked':''?> data-resource-type> Upload a file</label><label class="choice"><input type="radio" name="resource_type" value="link" <?=($item['resource_type']==='link')?'checked':''?> data-resource-type> Submit a web link</label></div></div>
<div class="full-field" data-file-field><label>Replace file <small><?php if ($item['resource_type']==='file' && !empty($item['original_name'])): ?>Current file: <?=e($item['original_name'])?>. Leave this empty to keep it.<?php else: ?>Choose a file to replace the current resource.<?php endif; ?></small><input type="file" name="resource_file" accept=".pdf,.mp4,.webm,.mp3,.wav,.m4a,.jpg,.jpeg,.png,.gif,.webp,.doc,.docx,.txt,.ppt,.pptx,.xls,.xlsx,.csv,.zip"></label></div>
<div class="full-field" data-link-field><label>Resource URL <small><?php if ($item['resource_type']==='link'): ?>Current link: <?=e($item['external_url'])?>. Enter a new URL to replace it, or leave it as it is.<?php else: ?>Enter the new web link.<?php endif; ?></small><input type="url" name="external_url" value="<?=e($item['resource_type']==='link'?$item['external_url']:'')?>" placeholder="https://example.com/resource"></label></div>
<div class="full-field"><span class="field-label">Visibility</span><div class="visibility-options"><label class="visibility-option"><input type="radio" name="visibility" value="public" <?=($item['visibility']==='public')?'checked':''?>><span><strong>Public</strong><small>Visible to everyone after approval.</small></span></label><label class="visibility-option"><input type="radio" name="visibility" value="private" <?=($item['visibility']==='private')?'checked':''?>><span><strong>Private</strong><small>Only you and authorized admins can access it.</small></span></label></div></div>
</div><div class="form-actions"><button class="button button-primary" type="submit">Save changes <span aria-hidden="true">→</span></button><a class="button button-quiet" href="view-resource.php?id=<?=(int)$item['id']?>">Cancel</a><span class="form-progress" aria-live="polite"></span></div></form></div></main><?php render_footer(); ?>
